# Test hypothesis H: within each column, seeds sorted by row; each maximal empty run
# (between consecutive seeds, or between edge and first/last seed) is painted with the
# color of its BOTTOM endpoint seed (for between-runs) or TOP-seed color for edge-above runs.
def f(inp):
    h=len(inp); out=[r[:] for r in inp]
    for c in range(len(inp[0])):
        seeds=[(r,inp[r][c]) for r in range(h) if inp[r][c]]
        for (a,col),(b,_nxt) in [(None,s[0]) for s in []]: pass
        # edge-above runs
        prev = None
        for idx,(r,v) in enumerate(seeds):
            if prev is None:
                for rr in range(0,r):
                    if out[rr][c]==0: out[rr][c]=v
            else:
                for rr in range(prev+1,r):
                    if out[rr][c]==0: out[rr][c]=v  # bottom-end rule
            prev=r
        # below last seed
        if seeds:
            for rr in range(seeds[-1][0]+1,h):
                if out[rr][c]==0: out[rr][c]=seeds[-1][1]
    return out
