    h=len(inp); w=len(inp[0])
    out=[r[:] for r in inp]
    for c in range(w):
        seeds=[(r,inp[r][c]) for r in range(h) if inp[r][c]]
        for idx,(r,v) in enumerate(seeds):
            # region above this seed (only if it's the topmost seed)
            if idx==0:
                for rr in range(0,r):
                    if out[rr][c]==0: out[rr][c]=v
            # region below previous seed down to this seed
